const express = require('express');
const app = express();
const port = 3000;

app.use(express.json());

// POST handler with input validation
app.post('/api', (req, res) => {
  const { name } = req.body;

  // Check if 'name' is missing or not a string
  if (name === undefined || typeof name !== 'string') {
    return res.status(400).json({ error: 'Missing or invalid "name" field. Please provide a valid string for the "name" field.' });
  }

  // Process the valid request
  res.json({ message: `Hello, ${name}!` });
});

app.listen(port, () => {
  console.log(`Server running on http://localhost:${port}`);
});

const http = require('http');

// Test cases
const testCases = [
  {
    name: 'Valid request',
    payload: JSON.stringify({ name: 'John' }),
    expectedStatus: 200,
  },
  {
    name: 'Missing name field',
    payload: JSON.stringify({}),
    expectedStatus: 400,
  },
  {
    name: 'Non-string name field',
    payload: JSON.stringify({ name: 123 }),
    expectedStatus: 400,
  },
];

// Run tests
const runTests = () => {
  testCases.forEach(({ name, payload, expectedStatus }) => {
    const req = http.request(
      {
        hostname: 'localhost',
        port: 3000,
        path: '/api',
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': payload.length,
        },
      },
      (res) => {
        let data = '';
        res.on('data', (chunk) => (data += chunk));
        res.on('end', () => {
          console.log(
            `${name}: Status=${res.statusCode} (Expected=${expectedStatus})`,
            'Response:', data
          );
        });
      }
    );

    req.on('error', (e) => {
      console.error(`Request error: ${e.message}`);
    });

    req.write(payload);
    req.end();
  });
};

// Wait for the server to start
setTimeout(runTests, 1000);

